 ctx.fillStyle='#738095';ctx.textBaseline='top';const ticks=Math.max(2,Math.min(8,Math.floor((right-left)/100)));for(let k=0;k<=ticks;k++){const y=p.y0+(p.y1-p.y0)*k/ticks;ctx.textAlign=k===0?'left':k===ticks?'right':'center';ctx.fillText(String(Math.round(y)),xx(y),bottom+8);}ctx.textAlign='left';ctx.fillText('积分',6,2);
