function plotFit(model,xLabel,yLabel){const canvas=$('calibrationPlot'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);const pts=model.points,ymin=Math.min(0,...pts.map(p=>p.y)),ymax=Math.max(1,...pts.map(p=>p.y)),x0=model.min,x1=model.max;const x=v=>42+(v-x0)/Math.max(1e-12,x1-x0)*370,y=v=>150-(v-ymin)/Math.max(1e-12,ymax-ymin)*125;ctx.strokeStyle='#deded4';ctx.strokeRect(42,12,370,138);ctx.strokeStyle='#30332c';ctx.beginPath();for(let i=0;i<=100;i++){const v=x0+(x1-x0)*i/100,p=C.predict(model,v,true);i?ctx.lineTo(x(v),y(p)):ctx.moveTo(x(v),y(p));}ctx.stroke();ctx.fillStyle='#be9238';for(const p of pts){ctx.beginPath();ctx.arc(x(p.x),y(p.y),3.5,0,2*Math.PI);ctx.fill();}ctx.fillStyle='#777b70';ctx.font='10px sans-serif';ctx.fillText(xLabel,350,174);ctx.fillText(yLabel,4,10);}
function render(){syncGelRotation();if(window.updateLaneSetup)window.updateLaneSetup();drawImage();drawProfile();renderResults();if(window.updateGelViewer)window.updateGelViewer();}
function canvasViewPoint(event){const canvas=$('image'),r=canvas.getBoundingClientRect(),f=gelFrame(),scale=Math.min(r.width/f.width,r.height/f.height),left=r.left+(r.width-f.width*scale)/2,top=r.top+(r.height-f.height*scale)/2;return {x:C.clamp((event.clientX-left)/scale,0,f.width),y:C.clamp((event.clientY-top)/scale,0,f.height)};}
