$('image').addEventListener('pointermove',guard(e=>{if(window.moveAnalysisPan&&window.moveAnalysisPan(e))return;if(drag){drag.end=canvasPoint(e);drag.viewEnd=canvasViewPoint(e);drawImage();}}));
$('image').addEventListener('pointerup',guard(e=>{if(window.endAnalysisPan&&window.endAnalysisPan())return;if(!drag)return;drag.end=canvasPoint(e);drag.viewEnd=canvasViewPoint(e);const r=dragRect(drag.start,drag.end),viewRegion=dragRect(drag.viewStart,drag.viewEnd),ends=[drag.start,drag.end],tool=val('tool');drag=null;if(tool==='laneAnchors'){window.acceptLaneAnchor(viewRegion);return;}else if(tool==='roi')state.roi=C.rect(r,ch().width,ch().height);else if(tool==='background')state.backgroundShape={...r,type:'rect'};else if(tool==='rect'||tool==='ellipse'){state.spots.push({...r,type:tool,id:nextID('S',state.spots)});state.spotSpec=null;measureSpots(false);}else if(tool==='lane'){const r=viewRegion,l={id:nextID('L',state.lanes),name:'手动泳道',xTop:r.x+r.w/2,xBottom:r.x+r.w/2,width:Math.max(2,r.w),y0:r.y,y1:r.y+r.h,orthogonal:true,...(gelRotation()?{frame:gelFrame()}:{})};validateRawLane(l,ch());state.lanes.push(l);laneID=l.id;newGeometry();}else if(tool==='band'){const c=ch(),l=lane(),key=bandKey(c,l),list=state.bands[key]||[];const ys=ends.map(p=>C.framePoint(l.frame,p).y),b={id:nextID('b',list),y0:Math.max(l.y0,Math.min(...ys)),y1:Math.min(l.y1,Math.max(...ys)),manual:true};if(b.y1<=b.y0)throw Error('条带须位于当前泳道内');if(list.some(a=>b.y0<a.y1&&b.y1>a.y0))throw Error('条带区域重叠；请先修正现有条带范围');list.push(C.measureBand(C.profile(c,l,options(c)),b,l));state.bands[key]=list.sort((a,b)=>a.y0-b.y0);invalidateCalibrations({targets:[{channel:c.id,lane:l.id,band:b.id}]});}history('手动工具',{tool,region:r});updateSelectors();render();}));
$('image').addEventListener('dblclick',guard(()=>{if(val('tool')==='lanePath'){const frame=gelRotation()?gelFrame():null,points=polygon.map(p=>C.framePoint(frame,p)).sort((a,b)=>a.y-b.y).filter((p,i,a)=>!i||p.y-a[i-1].y>1);if(points.length<2)throw Error('沿泳道从上到下点击至少两个点，双击结束');const l={id:nextID('L',state.lanes),name:'手动中心线',xTop:points[0].x,xBottom:points.at(-1).x,y0:points[0].y,y1:points.at(-1).y,width:num('laneWidth'),path:points,orthogonal:true,...(frame?{frame}: {})};validateRawLane(l,ch());state.lanes.push(l);laneID=l.id;polygon=[];newGeometry();return;}if(val('tool')!=='polygon')return;if(polygon.length<3)throw Error('至少点击三个顶点');state.spots.push({id:nextID('S',state.spots),type:'polygon',points:[...polygon]});polygon=[];state.spotSpec=null;measureSpots();history('手动多边形斑点');}));
$('tool').addEventListener('change',()=>{polygon=[];drag=null;$('canvasHint').textContent=val('tool')==='lanePath'?'沿泳道中心从上到下逐点点击，双击结束；宽度使用右侧泳道宽度。':val('tool')==='polygon'?'逐点点击勾勒斑点，双击结束；多边形积分按像素中心判定。':'拖动添加区域；选择工具可选泳道 / 斑点。坐标对应原始像素。';drawImage();});
function readLibrary(){try{const a=JSON.parse(localStorage.getItem('GelScope.markers.v1')||'[]');if(Array.isArray(a))library.push(...a.map(C.validateMarker).map(p=>({...p,builtIn:false})));}catch(e){notify('个人 Marker 库读取失败，可重新导入 JSON。');}}
function saveLibrary(){if(window.updateLaneSetup)window.updateLaneSetup();const custom=library.filter(p=>!p.builtIn);try{localStorage.setItem('GelScope.markers.v1',JSON.stringify(custom));}catch(e){notify('本机存储失败，请导出 Marker 库 JSON 保存。');}updateLibrary();}
function updateLibrary(){selectedOptions($('marker'),library,val('marker'));selectedOptions($('libraryMarker'),library,editingMarker);if(!editingMarker&&library.length)editingMarker=library[0].id;showMarker();}
function showMarker(){const m=library.find(m=>m.id===editingMarker);if(!m)return;for(const [id,key]of Object.entries({markerName:'name',markerUnit:'unit',markerSource:'source'}))$(id).value=m[key]||'';$('markerValues').value=m.values.join('\n');$('libraryMarker').value=m.id;$('markerInfo').textContent=m.builtIn?'内置参考；编辑保存会创建个人副本。':'个人 Marker，可编辑和导出。';}
$('libraryMarker').addEventListener('change',()=>{editingMarker=val('libraryMarker');showMarker();});
on('newMarker',()=>{editingMarker='';$('markerName').value='我的 Marker';$('markerValues').value='';$('markerSource').value='';$('markerInfo').textContent='填写按从上到下排列的数值后保存。';});
on('saveMarker',()=>{const old=library.find(p=>p.id===editingMarker),id=old&&!old.builtIn?old.id:crypto.randomUUID(),m=C.validateMarker({id,name:val('markerName').trim(),unit:val('markerUnit'),values:val('markerValues').trim().split(/[,，\s]+/),source:val('markerSource'),builtIn:false});if(old&&!old.builtIn)library[library.indexOf(old)]=m;else library.push(m);editingMarker=id;saveLibrary();notify('个人 Marker 已保存。');});
on('deleteMarker',()=>{const m=library.find(p=>p.id===editingMarker);if(!m||m.builtIn)throw Error('内置参考保留；可以删除自建条目');library=library.filter(p=>p!==m);editingMarker=library[0]?.id||'';saveLibrary();});
on('exportMarkers',()=>native('exportMarkers',{text:JSON.stringify({format:'GelScopeMarkers',version:1,markers:library.map(p=>({...p}))},null,2)}));on('importMarkers',()=>native('importMarkers'));
window.receiveMarkers=guard(packet=>{if(packet.format!=='GelScopeMarkers'||packet.version!==1||!Array.isArray(packet.markers)||packet.markers.length>500)throw Error('Marker 库格式无效');const imported=packet.markers.map(C.validateMarker);for(const p of imported){if(library.some(m=>m.name===p.name&&m.unit===p.unit&&JSON.stringify(m.values)===JSON.stringify(p.values)))continue;library.push({...p,id:crypto.randomUUID(),builtIn:false});}saveLibrary();notify('Marker 库已合并，重复条目已跳过。');});
function settings(){return Object.fromEntries(settingIDs.map(id=>[id,$(id).type==='checkbox'?$(id).checked:val(id)]));}
function project(){window.prepareGelProject?.();return {format:'GelScopeProject',version:1,application:'胶个朋友 2.4.0',created:new Date().toISOString(),settings:settings(),selection:{channelID,laneID,target:val('targetChannel'),reference:val('referenceChannel'),standard:val('standardLane')},state:{...state,viewAngle:gelRotation(),viewCamera:window.currentGelCamera?.(),channels:state.channels.map(({data,...c})=>({...c,raw:c.raw||base64(rawBytes(data))})),mwModels:undefined,quantityModel:undefined,spotModel:undefined},markers:library.filter(m=>!m.builtIn)};}
function checkGeometry(s,channels){const c=channels[0];if(s.laneAnchorCount!==undefined&&(!Number.isInteger(s.laneAnchorCount)||s.laneAnchorCount!==0&&(s.laneAnchorCount<3||s.laneAnchorCount>200)))throw Error('项目预览泳道数量无效');if(s.viewAngle!==undefined)C.finite(s.viewAngle,'项目旋转角度');if(s.viewCamera&&(!['fit','fill','manual'].includes(s.viewCamera.mode)||!Number.isFinite(s.viewCamera.scale)||s.viewCamera.scale<=0||s.viewCamera.scale>4096||!Number.isFinite(s.viewCamera.center?.x)||!Number.isFinite(s.viewCamera.center?.y)))throw Error('项目视野状态无效');if(!Array.isArray(s.lanes)||s.lanes.length>200||!Array.isArray(s.spots)||s.spots.length>1000||!s.bands||typeof s.bands!=='object')throw Error('项目标注格式无效');if(new Set(s.lanes.map(l=>l.id)).size!==s.lanes.length)throw Error('项目泳道 ID 重复');for(const l of s.lanes){const size=l.frame?C.validateFrame(l.frame,c):c;if(l.markerSpec)C.validateMarker(l.markerSpec);for(const k of ['xTop','xBottom','width','y0','y1'])C.finite(l[k]);if(l.width<1||l.width>size.width||l.y0<0||l.y1>size.height||l.y1<=l.y0||l.xTop<0||l.xTop>=size.width||l.xBottom<0||l.xBottom>=size.width)throw Error('项目泳道坐标无效');if(l.path){if(!Array.isArray(l.path)||l.path.length<2||l.path.length>500||l.path.some((p,i)=>!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>=size.width||p.y<l.y0||p.y>l.y1||(i&&p.y<=l.path[i-1].y))||Math.abs(l.path[0].y-l.y0)>1e-6||Math.abs(l.path.at(-1).y-l.y1)>1e-6)throw Error('项目泳道中心线无效');}validateRawLane(l,c);}if(s.laneAnchorFrame)C.validateFrame(s.laneAnchorFrame,c);for(const [key,a] of Object.entries(s.bands)){const owner=s.lanes.find(l=>key.endsWith('|'+l.id)),height=owner?.frame?.height||c.height;if(!Array.isArray(a)||a.length>2000)throw Error('项目条带过多');if(new Set(a.map(b=>b.id)).size!==a.length)throw Error('项目条带 ID 重复');for(const b of a)if(!Number.isFinite(b.y0)||!Number.isFinite(b.y1)||b.y0<0||b.y1>height||b.y1<=b.y0)throw Error('项目条带坐标无效');}for(const spot of s.spots){if(!['rect','ellipse','polygon'].includes(spot.type))throw Error('项目斑点形状无效');if(spot.type==='polygon'&&(!Array.isArray(spot.points)||spot.points.length>2000||spot.points.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.y))))throw Error('项目多边形无效');C.shapeBounds(spot,c.width,c.height);}if(s.colony&&(!Array.isArray(s.colony.items)||s.colony.items.length>100000))throw Error('项目菌落数据无效');}
window.receiveProject=guard(async p=>{if(p.format!=='GelScopeProject'||p.version!==1||!p.state||!Array.isArray(p.state.channels))throw Error('不是有效的 GelScope 项目');const channels=await Promise.all(p.state.channels.map(decodeChannel));validateDimensions(channels);checkGeometry(p.state,channels);for(const [id,value]of Object.entries(p.settings||{}))if(settingIDs.includes(id)){if($(id).type==='checkbox')$(id).checked=Boolean(value);else $(id).value=String(value);}state={...p.state,channels,history:Array.isArray(p.state.history)?p.state.history.slice(-2000):[]};state.roi=C.rect(state.roi||{x:0,y:0,w:channels[0].width,h:channels[0].height},channels[0].width,channels[0].height);channelID=p.selection?.channelID||channels[0].id;laneID=p.selection?.laneID||'';if(!channels.some(c=>c.id===channelID))channelID=channels[0].id;for(const m of p.markers||[]){const marker=C.validateMarker(m);if(!library.some(a=>a.id===marker.id))library.push({...marker,builtIn:false});}saveLibrary();imageCache=null;updateSelectors();for(const [id,key]of [['targetChannel','target'],['referenceChannel','reference'],['standardLane','standard']])if(p.selection?.[key])$(id).value=p.selection[key];const wb=state.wb;remeasure();state.wb=wb||[];history('重新打开项目');render();if(window.showGelViewer)window.showGelViewer(true);notify('项目已打开，原始像素校验通过。');});
function csv(columns,rows){const cell=v=>{let s=String(v??'');if(typeof v==='string'&&/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};return '\uFEFF'+columns.map(c=>cell(c[0])).join(',')+'\r\n'+rows.map(r=>columns.map(c=>cell(typeof c[1]==='function'?c[1](r):r[c[1]])).join(',')).join('\r\n');}
function report(){ch();const bands=allBandRows(),spots=state.spotResults||[],colonies=state.colony?.items||[],wb=state.wb||[],bcols=bandColumns(),scols=[['channel','channel'],['spot','id'],['area','area'],['raw','rawVolume'],['background','backgroundVolume'],['net','netVolume'],['quantity','quantity'],['unit','unit'],['saturated','saturated']],ccols=[['id','id'],['x','x'],['y','y'],['area','area'],['circularity','circularity'],['manual','manual']],wcols=[['lane','lane'],['target','target'],['loading','loading'],['factor','factor'],['normalised','normalised'],['fold','fold'],['warning','warning']];const details={format:'GelScopeAnalysisReport',version:1,generated:new Date().toISOString(),application:'胶个朋友 2.4.0',disclaimer:'独立实现的研究辅助算法；尚未与 GeneTools 做一致性验证。数字信号积分不等于绝对分子数量。',sources:state.channels.map(({data,raw,...c})=>c),viewAngle:gelRotation(),settings:settings(),roi:state.roi,lanes:state.lanes,spots:state.spots,backgroundShape:state.backgroundShape,mwStandards:state.mwSpec,mwFit:state.mwModels,quantityStandards:state.quantitySpec,quantityFit:state.quantityModel,spotStandards:state.spotSpec,spotFit:state.spotModel,wbSpec:state.wbSpec,colony:state.colony,results:{bands,spots,wb},history:state.history};const snapshot=$('image').toDataURL('image/png');const html='<!doctype html><html lang="zh"><meta charset="utf-8"><title>胶个朋友 分析报告</title><style>body{font:13px -apple-system,sans-serif;margin:40px;color:#262822}h1{font-size:30px}h2{margin-top:35px}table{border-collapse:collapse;font-size:11px;width:100%}td,th{border:1px solid #ddd;padding:7px;text-align:left}th{background:#f4f3ed}img{max-width:900px;width:100%}pre{white-space:pre-wrap;word-break:break-all;background:#f6f5ef;padding:15px}.note{background:#faf3dc;padding:16px}@media print{body{margin:15px}table{font-size:9px}tr{break-inside:avoid}}</style><h1>胶个朋友 · 胶图分析报告</h1><p>'+esc(details.generated)+'</p><p class="note">'+esc(details.disclaimer)+'<br>显示图只用于观察；定量使用未经显示调整的原始像素。图像需预先对齐；不提供光谱解混、仪器控制或 GLP / 21 CFR Part 11 认证。</p><img alt="分析标注快照" src="'+snapshot+'"><h2>条带结果</h2>'+table(bcols,bands)+'<h2>Western 归一化</h2>'+table(wcols,wb)+'<h2>Spot blot</h2>'+table(scols,spots)+'<h2>菌落计数：'+colonies.length+'</h2>'+table(ccols,colonies)+'<h2>源文件与像素 SHA-256</h2>'+table([['通道','name'],['文件','source'],['位深','bitDepth'],['文件 SHA-256','sourceHash'],['原始像素 SHA-256','rawHash']],details.sources)+'<h2>参数、标定、手动修正记录</h2><pre>'+esc(JSON.stringify(details,null,2))+'</pre></html>';native('report',{files:[{name:'报告.html',contents:html},{name:'条带.csv',contents:csv(bcols,bands)},{name:'Western.csv',contents:csv(wcols,wb)},{name:'斑点.csv',contents:csv(scols,spots)},{name:'菌落.csv',contents:csv(ccols,colonies)},{name:'参数与结果.json',contents:JSON.stringify(details,null,2)}]});history('导出报告');}
on('report',report);
on('demo',()=>{const width=240,height=260,channels=[];for(let k=0;k<2;k++){const data=new Uint16Array(width*height);for(let y=0;y<height;y++)for(let x=0;x<width;x++){let v=100+y*.2;for(const center of [40,95,150,205])if(Math.abs(x-center)<=10)for(const [j,yy]of [50,110,180,225].entries())v+=(k?800:1500)*(1+j*.3)*Math.exp(-(((y-yy)/3)**2));data[y*width+x]=Math.round(v);}channels.push({id:'demo'+k,name:'合成演示 · '+(k?'内参':'目标'),width,height,bitDepth:16,data,raw:base64(rawBytes(data)),encoding:'uint16le',source:'SYNTHETIC DEMO — 非实验数据',sourceHash:'合成示例，无源文件',rawHash:'',polarity:'bright',ceiling:65535});}state={channels,lanes:C.equalLanes({x:12,y:20,w:220,h:225},4,20),bands:{},spots:[],wb:[],colony:null,history:[],roi:{x:12,y:20,w:220,h:225},mwSpec:null,quantitySpec:null,spotSpec:null};channelID=channels[0].id;laneID='L1';$('background').value='border';$('targetY0').value=100;$('targetY1').value=120;$('referenceY0').value=170;$('referenceY1').value=190;clearCalibrationInputs();for(const c of channels)for(const l of state.lanes)detect(c,l);imageCache=null;history('载入合成演示');updateSelectors();render();notify('这是合成演示数据，不是实验测量。可练习标定、归一化与报告导出。');});
